package com.nostrvault.service

import android.content.Context

/**
 * Keys generated by setup on this device that have not published a given
 * list yet. Such a key cannot have that list anywhere, so "no list found" is
 * the truth, not a relay that hasn't answered. Without it one silent relay
 * leaves a new account unable to follow anyone (the follow is queued) and
 * the Fill your feed guide never starts.
 *
 * Kept per list kind: the follow list (3) and the hashtag list (10015). The
 * scan-join follow publishes a kind 3 at the end of setup; that clears only
 * kind 3, so the guide's first hashtag save still knows it starts from empty
 * (2026-11-26: with one relay down it was rolled back). Each kind is cleared
 * once a relay accepts its first publish, not at sign: a list refused
 * everywhere is on no relay, so the key is still fresh after a restart
 * (Tron, 3.3.1 ship check §2). iOS: FreshAccountKeys.swift.
 */
object FreshAccountKeys {
    internal const val PREFS = "fresh_account_keys"
    private const val KEY = "keys"

    /** The lists a brand-new key starts without. */
    val KINDS: Set<Int> = setOf(3, 10015)

    private fun prefs(context: Context) = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)

    private fun stored(context: Context): Set<String> = prefs(context).getStringSet(KEY, emptySet()).orEmpty()

    fun mark(context: Context, hex: String) {
        if (hex.isEmpty()) return
        prefs(context).edit().putStringSet(KEY, marked(stored(context), hex)).apply()
    }

    fun isFresh(context: Context, hex: String, kind: Int): Boolean = isFresh(stored(context), hex, kind)

    fun clear(context: Context, hex: String, kind: Int) {
        val keys = stored(context)
        val next = cleared(keys, hex, kind)
        if (next != keys) prefs(context).edit().putStringSet(KEY, next).apply()
    }

    // ── Pure rules (unit tested) ──────────────────────────────────
    // Entries are "<hex>:<kind>". A bare "<hex>" was written before the
    // per-kind split and means every kind is still fresh.

    internal fun marked(keys: Set<String>, hex: String): Set<String> =
        keys - hex + KINDS.map { "$hex:$it" }

    internal fun isFresh(keys: Set<String>, hex: String, kind: Int): Boolean =
        hex.isNotEmpty() && (hex in keys || "$hex:$kind" in keys)

    internal fun cleared(keys: Set<String>, hex: String, kind: Int): Set<String> {
        if (hex.isEmpty()) return keys
        // An old bare mark becomes the other kinds, still fresh.
        val expanded = if (hex in keys) keys - hex + KINDS.map { "$hex:$it" } else keys
        val next = expanded - "$hex:$kind"
        return if (next == expanded && hex !in keys) keys else next
    }
}
